#include <string>
#include <vector>

class Solution {
public:
    std::string addSpaces(std::string s, std::vector<int>& spaces) {
        std::string ans;
        ans.reserve(s.size() + spaces.size());

        int spIdx = 0, m = spaces.size();
        for (int i = 0; i < (int)s.size(); ++i) {
            if (spIdx < m && i == spaces[spIdx]) {
                ans += ' ';
                spIdx++;
            }
            ans += s[i];
        }
        return ans;
    }
};

class Solution {
    public String addSpaces(String s, int[] spaces) {
        StringBuilder sb = new StringBuilder(s.length() + spaces.length);
        int spIdx = 0, m = spaces.length;

        for (int i = 0; i < s.length(); i++) {
            if (spIdx < m && i == spaces[spIdx]) {
                sb.append(' ');
                spIdx++;
            }
            sb.append(s.charAt(i));
        }
        return sb.toString();
    }
}

/**
 * @param {string} s
 * @param {number[]} spaces
 * @return {string}
 */
var addSpaces = function(s, spaces) {
    const parts = [];
    let prev = 0;
    for (const idx of spaces) {
        parts.push(s.slice(prev, idx));
        prev = idx;
    }
    parts.push(s.slice(prev));
    return parts.join(' ');
};
